/**
 * Route suggestions for planned runs (suggest-run-route,
 * view-route-suggestions): the athlete's own past runs from a start with
 * history, routes stitched from sections of past runs between via points,
 * plus routes generated by OpenRouteService, ranked by terrain
 * and road crossings (OpenStreetMap). One home for the rules; the tools
 * format, the app draws.
 */
import { CallCancelledError } from "./callScope";
import {
  isAbortError,
  RateLimitError,
  RequestTimeoutError,
} from "./fetchClient";
import {
  bestRepeatHill,
  REPEAT_HILL_MAX_GRADE_PCT,
  REPEAT_HILL_MAX_M,
  REPEAT_HILL_MIN_GRADE_PCT,
  REPEAT_HILL_MIN_M,
} from "./hillAnalysis";
import {
  legOptions,
  planStitches,
  STITCH_FILL_CALLS,
  stitchAnchors,
  stitchedCandidate,
} from "./historyLegs";
import { listPlannedWorkouts } from "./intervalsClient";
import {
  haversineMeters,
  type LatLng,
  parseLatLng,
  type RouteTrack,
} from "./mapAnchors";
import {
  geocode,
  OrsApiError,
  type OrsRoute,
  type OrsRouteRequest,
  orsRoute,
  type Place,
  PRECISE_LAYERS,
} from "./orsClient";
import { crossingsPerKm, loadCrossings } from "./overpassClient";
import { NO_PROGRESS, type ReportProgress } from "./progress";
import {
  dedupeRoutes,
  MAX_PAST_CANDIDATES,
  matchPastRuns,
  outAndBack,
  PAST_POOL,
  type RouteCandidate,
  type RouteShape,
  rankGenerated,
  rankPast,
  sameRoute,
  stretchWaypoints,
  type Terrain,
  type TerrainBands,
  terrainBands,
  thereAndBack,
  trackClimb,
} from "./routeCandidates";
import {
  clusterStarts,
  loadRunStarts,
  nearestCluster,
  OUTDOOR_RUN_TYPES,
  type RunStart,
  type StartCluster,
} from "./startClusters";
import { addDays, daysBetween } from "./utils/localDate";

export const GENERATED_AT_HOME = 1;
export const GENERATED_AWAY = 3;
/** Seeds tried beyond those wanted, so ranking has a choice. */
export const EXTRA_SEEDS = 1;
export const GENERATED_DISTANCE_TOLERANCE = 0.05;
/** A generated loop or out-and-back further off the distance than this is dropped (a via route's nearest is kept, with a warning). */
export const GENERATED_MAX_MISS = 0.25;
/** One request plus one rescale lands within 5% (docs/api-notes.md). */
export const MAX_FIT_CALLS = 2;
/** A first loop off by more than this factor is not rescaled: ORS gave 39 km for 6 km, and the rescale 1 km. */
const MAX_RESCALE_RATIO = 2;
/** A rescale moves the asked length by at most this factor either way. */
const RESCALE_CLAMP: [number, number] = [0.75, 1.33];
/** ORS calls one tool call may make: the key allows 200 a day. */
export const ORS_CALL_BUDGET = 12;
export const PLANNED_RUN_LOOKAHEAD_DAYS = 14;

export interface RouteSuggestionArgs {
  date?: string;
  days?: number;
  distanceKm?: number;
  start?: string;
  end?: string;
  /** One place, or places to pass in order. */
  via?: string | string[];
  shape?: RouteShape;
  terrain?: Terrain;
}

/** What the engine reads from config, passed in so tests need no env. */
export interface SuggestionEnv {
  orsKey: string | null;
  homeStart: LatLng | null;
  today: string;
}

export type StartSource = "argument" | "env" | "inferred";

export interface RunSuggestion {
  event_id: number | null;
  date: string;
  name: string;
  description: string | null;
  distance_m: number;
  distance_source: "argument" | "event";
  start: Place & { source: StartSource; history_runs: number };
  end: Place | null;
  /** In the order the route passes them. */
  via: Place[];
  shape: RouteShape;
  terrain: Terrain;
  candidates: RouteCandidate[];
  warnings: string[];
}

export interface RouteSuggestions {
  runs: RunSuggestion[];
  generation_available: boolean;
  warnings: string[];
}

/** A request the engine cannot answer, worded for the athlete. */
export class RouteSuggestionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RouteSuggestionError";
  }
}

interface PlannedRun {
  event_id: number | null;
  date: string;
  name: string;
  description: string | null;
  distance_m: number;
  distance_source: "argument" | "event";
}

/** ORS calls left in this tool call; `failure` is set once ORS fails, and no call is made after it. */
export interface Budget {
  calls: number;
  failure: string | null;
}

export const canCall = (budget: Budget) =>
  budget.calls > 0 && budget.failure === null;

/**
 * One ORS call charged to the budget; null when it fails, which stops
 * generation for the rest of the tool call, except a `missable` call's 404:
 * a stretch point ORS cannot reach (in the harbour, say) costs only that try.
 */
async function orsCall(
  key: string,
  request: OrsRouteRequest,
  budget: Budget,
  missable = false,
): Promise<OrsRoute | null> {
  budget.calls -= 1;
  try {
    return await orsRoute(key, request);
  } catch (error) {
    // A cancelled call stops; any other failure keeps what was generated so far.
    if (error instanceof CallCancelledError || isAbortError(error)) throw error;
    if (
      missable &&
      error instanceof OrsApiError &&
      error.response.status === 404
    )
      return null;
    budget.failure = orsProblem(error);
    return null;
  }
}

/** Why ORS did not answer, as a clause; branches on type and status only (its messages carry coordinates). */
export function orsProblem(error: unknown): string {
  if (error instanceof RateLimitError)
    return "OpenRouteService's rate limit was reached";
  if (error instanceof OrsApiError) {
    const { status } = error.response;
    if (status === 401 || status === 403)
      return "OpenRouteService rejected ORS_API_KEY";
    if (status === 404)
      return "OpenRouteService found no walkable path near that point";
    return `OpenRouteService answered HTTP ${status}`;
  }
  return "the request to OpenRouteService failed";
}

const km = (meters: number) => (meters / 1000).toFixed(1);

async function plannedRuns(
  apiKey: string,
  oldest: string,
  days: number,
  distanceKm: number | undefined,
): Promise<PlannedRun[]> {
  const newest = addDays(
    oldest,
    (days > 1 ? days : PLANNED_RUN_LOOKAHEAD_DAYS) - 1,
  );
  const events = (await listPlannedWorkouts(apiKey, { oldest, newest })).filter(
    (e) => OUTDOOR_RUN_TYPES.has(e.type ?? ""),
  );
  const chosen = days > 1 ? events : events.slice(0, 1);
  if (chosen.length === 0) {
    if (distanceKm === undefined) {
      throw new RouteSuggestionError(
        `No planned run from ${oldest} to ${newest}. Pass distanceKm to plan a route anyway.`,
      );
    }
    return [
      {
        event_id: null,
        date: oldest,
        name: "Run",
        description: null,
        distance_m: distanceKm * 1000,
        distance_source: "argument",
      },
    ];
  }
  return chosen.map((e) => ({
    event_id: e.id,
    date: e.start_date_local.slice(0, 10),
    name: e.name ?? "Planned run",
    description: e.description ?? null,
    distance_m:
      distanceKm !== undefined ? distanceKm * 1000 : (e.distance ?? 0),
    distance_source: distanceKm !== undefined ? "argument" : "event",
  }));
}

/** The ORS key a place name needs to be looked up. */
function requireGeocoder(
  text: string,
  env: Pick<SuggestionEnv, "orsKey">,
): string {
  if (env.orsKey) return env.orsKey;
  throw new RouteSuggestionError(
    `"${text}" is a place name, and looking up place names needs ORS_API_KEY. Pass it as lat,lng instead.`,
  );
}

/** A place from "lat,lng" or a name looked up near `focus`; a lookup failure is a {@link RouteSuggestionError}. */
export async function resolvePlace(
  text: string,
  env: Pick<SuggestionEnv, "orsKey">,
  focus: LatLng | null,
): Promise<Place> {
  const point = parseLatLng(text);
  if (point) return { label: text.trim(), point };
  const key = requireGeocoder(text, env);
  let hit: Place | null;
  try {
    hit = await geocode(key, text, focus);
  } catch (error) {
    // A timeout too: its message is the geocode URL, which carries the text and focus point.
    if (
      error instanceof RateLimitError ||
      error instanceof OrsApiError ||
      error instanceof RequestTimeoutError
    ) {
      throw new RouteSuggestionError(
        `Could not look up "${text}": ${orsProblem(error)}.`,
      );
    }
    throw error;
  }
  if (!hit)
    throw new RouteSuggestionError(
      `No place matched "${text}". Add the suburb or city, or pass lat,lng.`,
    );
  return hit;
}

/**
 * Why a looked-up via is refused: Pelias placed it no better than a suburb
 * or city, and routing through that centre goes somewhere else. Null for a
 * precise match or a lat,lng. Vias only: a suburb is a fair start, end or
 * heading.
 */
export function coarseVia(place: Place, text: string): string | null {
  if (!place.match || PRECISE_LAYERS.has(place.match.type)) return null;
  return `"${text.trim()}" matched only ${place.match.name} (a ${place.match.type}), so it was not routed; pass lat,lng for it.`;
}

async function resolveStart(
  text: string | undefined,
  env: SuggestionEnv,
  clusters: StartCluster[],
): Promise<Place & { source: StartSource }> {
  if (text) {
    const focus = env.homeStart ?? clusters[0]?.center ?? null;
    return { ...(await resolvePlace(text, env, focus)), source: "argument" };
  }
  if (env.homeStart)
    return {
      label: "Home start (HOME_START)",
      point: env.homeStart,
      source: "env",
    };
  const top = clusters[0];
  if (!top)
    throw new RouteSuggestionError(
      "No recent run has GPS to infer your usual start from. Pass start, or set HOME_START.",
    );
  const count = top.runs.length;
  return {
    label: `Usual start (${count} recent run${count === 1 ? "" : "s"})`,
    point: top.center,
    source: "inferred",
  };
}

/**
 * A route near `target_m` in up to {@link MAX_FIT_CALLS} tries: `request`
 * turns a knob (a loop's asked length, a via route's stretch) into an ORS
 * request and `length` measures the answer. A miss over 5% scales the knob
 * once by the length wanted over the length it added past `floor_m`, by at
 * most {@link RESCALE_CLAMP}, unless that is off by more than
 * {@link MAX_RESCALE_RATIO} times. The try nearest the target; null when no
 * call could be made, the first failed, or it went by ferry.
 */
export async function fitToTarget(
  key: string,
  fit: {
    target_m: number;
    floor_m: number;
    knob: number;
    request: (knob: number) => OrsRouteRequest;
    length: (route: OrsRoute) => number;
    missable?: boolean;
  },
  budget: Budget,
  progress: ReportProgress,
): Promise<OrsRoute | null> {
  const miss = (route: OrsRoute) => Math.abs(fit.length(route) - fit.target_m);
  let knob = fit.knob;
  let best: OrsRoute | null = null;
  for (let call = 0; call < MAX_FIT_CALLS && canCall(budget); call++) {
    progress(`Generating a route (try ${call + 1})`);
    const route = await orsCall(key, fit.request(knob), budget, fit.missable);
    // A ferry is never a run; avoid_features should keep ORS off one, so this is a backstop.
    if (!route || route.ferry_m > 0) break;
    if (!best || miss(route) < miss(best)) best = route;
    if (miss(route) <= fit.target_m * GENERATED_DISTANCE_TOLERANCE) break;
    const ratio =
      (fit.target_m - fit.floor_m) / (fit.length(route) - fit.floor_m);
    if (!(ratio >= 1 / MAX_RESCALE_RATIO && ratio <= MAX_RESCALE_RATIO)) break;
    knob *= Math.min(RESCALE_CLAMP[1], Math.max(RESCALE_CLAMP[0], ratio));
  }
  return best;
}

/**
 * Routes through the via points toward `target_m`: the via points alone
 * first, then, when that is short, one stretched route per seed
 * ({@link stretchWaypoints}), its first stretch set from the gap and how far
 * the streets wander from a straight line. Every route made, the unstretched
 * one first; the caller ranks them and warns when none is close.
 */
async function fitVia(
  key: string,
  plan: {
    start: LatLng;
    via: LatLng[];
    shape: "loop" | "out-and-back";
    target_m: number;
  },
  seeds: number[],
  budget: Budget,
  progress: ReportProgress,
): Promise<OrsRoute[]> {
  // An out-and-back's route is the way out; it is run twice.
  const [waypoints, laps] =
    plan.shape === "loop"
      ? [[plan.start, ...plan.via, plan.start], 1]
      : [[plan.start, ...plan.via], 2];
  if (!canCall(budget)) return [];
  progress("Routing through the via points");
  const first = await orsCall(key, { waypoints }, budget);
  if (!first || first.ferry_m > 0) return [];
  const floor_m = laps * first.distance_m;
  const gap = plan.target_m - floor_m;
  // Close enough, or already too long: a via point cannot be left out.
  if (gap <= plan.target_m * GENERATED_DISTANCE_TOLERANCE) return [first];
  let straight = 0;
  for (let i = 1; i < waypoints.length; i++)
    straight += haversineMeters(waypoints[i - 1]!, waypoints[i]!);
  const streets =
    straight > 0 ? Math.min(2, Math.max(1, first.distance_m / straight)) : 2;
  const routes = [first];
  for (const seed of seeds) {
    const route = await fitToTarget(
      key,
      {
        target_m: plan.target_m,
        floor_m,
        knob: gap / (laps * streets),
        request: (extra_m) => ({
          waypoints: stretchWaypoints(waypoints, plan.shape, extra_m, seed),
        }),
        length: (r) => laps * r.distance_m,
        missable: true,
      },
      budget,
      progress,
    );
    if (route) routes.push(route);
  }
  return routes;
}

function generatedCandidate(
  route: OrsRoute,
  shape: RouteShape,
  track: RouteTrack = shape === "out-and-back"
    ? outAndBack(route.track)
    : route.track,
): RouteCandidate {
  return {
    kind: "generated",
    activity_id: null,
    name:
      shape === "point-to-point"
        ? "New route"
        : shape === "out-and-back"
          ? "New out-and-back"
          : "New loop",
    date: null,
    shape,
    distance_m: Math.round(track.distance.at(-1) ?? route.distance_m),
    climb_m: trackClimb(track.altitude),
    path_share: route.path_share,
    crossings_per_km: null,
    hill: null,
    summary:
      route.way_names.length > 0
        ? `via ${route.way_names.join(", ")}`
        : "New route",
    track,
  };
}

/**
 * Via routes along the athlete's own lines (historyLegs.ts): sections of
 * past runs between the anchors, ORS filling only what no run covers. A fill
 * is missable (a 404 drops that route only); the run's fills spend at most
 * {@link STITCH_FILL_CALLS}, and one the two routes share is routed once.
 * Without a key, only a route needing no fill is made.
 */
async function stitch(
  key: string | null,
  plan: {
    start: LatLng;
    end: LatLng | null;
    via: LatLng[];
    shape: RouteShape;
    target_m: number;
  },
  runs: RunStart[],
  budget: Budget,
  progress: ReportProgress,
): Promise<RouteCandidate[]> {
  if (plan.via.length === 0) return [];
  const anchors = stitchAnchors(plan.start, plan.via, plan.shape, plan.end);
  const options = anchors
    .slice(1)
    .map((to, i) => legOptions(runs, anchors[i]!, to));
  const plans = planStitches(options, anchors, plan.target_m, plan.shape);
  const routed = new Map<string, RouteTrack | null>();
  let calls = STITCH_FILL_CALLS;
  const made: RouteCandidate[] = [];
  for (const stitchPlan of plans) {
    const fills: (RouteTrack | null)[] = [];
    for (const piece of stitchPlan.pieces) {
      if (piece.kind !== "fill") continue;
      const id = JSON.stringify(piece.waypoints);
      if (!routed.has(id)) {
        if (!key || calls <= 0 || !canCall(budget)) break;
        calls -= 1;
        progress("Joining your past runs");
        const route = await orsCall(
          key,
          { waypoints: piece.waypoints },
          budget,
          true,
        );
        routed.set(id, route && route.ferry_m === 0 ? route.track : null);
      }
      const fill = routed.get(id) ?? null;
      fills.push(fill);
      if (!fill) break;
    }
    const candidate = stitchedCandidate(stitchPlan, fills, plan.shape);
    if (candidate) made.push(candidate);
  }
  return dedupeRoutes(made);
}

/** Every generated route tried for a run (duplicates removed); the caller ranks and keeps the wanted number. */
async function generate(
  key: string,
  plan: {
    start: LatLng;
    end: LatLng | null;
    via: LatLng[];
    shape: RouteShape;
    target_m: number;
  },
  want: number,
  seedBase: number,
  budget: Budget,
  progress: ReportProgress,
): Promise<RouteCandidate[]> {
  const { start, end, via, shape, target_m } = plan;
  if (shape === "point-to-point") {
    if (!canCall(budget) || !end) return [];
    const route = await orsCall(
      key,
      { waypoints: [start, ...via, end] },
      budget,
    );
    if (!route || route.ferry_m > 0) return [];
    return [generatedCandidate(route, shape)];
  }
  const seeds = Array.from(
    { length: want + EXTRA_SEEDS },
    (_, k) => seedBase + k,
  );
  if (via.length > 0) {
    const routes = await fitVia(
      key,
      { start, via, shape, target_m },
      seeds,
      budget,
      progress,
    );
    return dedupeRoutes(
      routes.map((route) =>
        generatedCandidate(
          route,
          shape,
          shape === "out-and-back" ? thereAndBack(route.track) : route.track,
        ),
      ),
    );
  }
  const tried: RouteCandidate[] = [];
  for (const seed of seeds) {
    const route = await fitToTarget(
      key,
      {
        target_m,
        floor_m: 0,
        knob: target_m,
        request: (length_m) => ({
          waypoints: [start],
          roundTrip: { length_m, seed },
        }),
        length: (r) => r.distance_m,
      },
      budget,
      progress,
    );
    // Null with budget left (a ferry) moves to the next seed; a spent or failed budget makes no more calls.
    if (route) tried.push(generatedCandidate(route, shape));
  }
  return dedupeRoutes(tried);
}

/**
 * The first ORS seed for a run: from its date (and its place among earlier
 * runs that day), so a week call and a one-run call for the same day ask
 * ORS for the same loops. shortcut: a third run in one day can share seeds
 * with the next day's; fine while two runs a day is the most planned.
 */
function seedBase(date: string, earlier: PlannedRun[], want: number): number {
  const sameDay = earlier.filter((r) => r.date === date).length;
  return (
    daysBetween("2000-01-01", date) * 10 + 1 + sameDay * (want + EXTRA_SEEDS)
  );
}

/** Suggestions for every planned run in the window; see the module comment. */
export async function loadRouteSuggestions(
  apiKey: string,
  args: RouteSuggestionArgs,
  env: SuggestionEnv,
  progress: ReportProgress = NO_PROGRESS,
): Promise<RouteSuggestions> {
  const shape: RouteShape =
    args.shape ?? (args.end ? "point-to-point" : "loop");
  const terrain: Terrain = args.terrain ?? "any";
  // Argument mistakes are reported before any history is read.
  if (shape === "point-to-point" && !args.end)
    throw new RouteSuggestionError(
      "A point-to-point route needs an end place.",
    );
  const viaTexts = typeof args.via === "string" ? [args.via] : (args.via ?? []);
  for (const text of [args.start, args.end, ...viaTexts]) {
    if (text && !parseLatLng(text)) requireGeocoder(text, env);
  }
  const planned = await plannedRuns(
    apiKey,
    args.date ?? env.today,
    args.days ?? 1,
    args.distanceKm,
  );

  const { runs: history, skipped } = await loadRunStarts(
    apiKey,
    env.today,
    progress,
  );
  const clusters = clusterStarts(history, env.today);
  const bands: TerrainBands = terrainBands(history);
  const warnings: string[] = [];
  if (skipped > 0) {
    warnings.push(
      `${skipped} recent run${skipped === 1 ? "" : "s"} had no GPS track or could not be read and ${skipped === 1 ? "was" : "were"} left out of the start history.`,
    );
  }

  const start = await resolveStart(args.start, env, clusters);
  const end = args.end ? await resolvePlace(args.end, env, start.point) : null;
  const via = await Promise.all(
    viaTexts.map(async (text) => {
      const found = await resolvePlace(text, env, start.point);
      const problem = coarseVia(found, text);
      if (problem) throw new RouteSuggestionError(problem);
      return found;
    }),
  );

  const cluster = nearestCluster(clusters, start.point);
  const want = cluster ? GENERATED_AT_HOME : GENERATED_AWAY;
  const budget: Budget = { calls: ORS_CALL_BUDGET, failure: null };
  const usedPast = new Set<string>();
  let crossingsMissing = false;
  const runs: RunSuggestion[] = [];

  for (const [index, run] of planned.entries()) {
    const runWarnings: string[] = [];
    let candidates: RouteCandidate[] = [];
    if (run.distance_m <= 0) {
      runWarnings.push("This planned run has no distance; pass distanceKm.");
    } else {
      const matched = cluster
        ? matchPastRuns(cluster.runs, {
            target_m: run.distance_m,
            shape,
            terrain,
            today: env.today,
            exclude: usedPast,
            bands,
            via: via.map((p) => p.point),
          })
        : [];
      if (terrain === "hill-repeats") {
        // Hills are found on every match before the cut, so a hilly loop ranked 7th still makes the pool.
        for (const c of matched)
          c.hill = bestRepeatHill(c.track.distance, c.track.altitude);
        matched.sort((a, b) => Number(!a.hill) - Number(!b.hill));
      }
      const pool = matched.slice(0, PAST_POOL);
      const plan = {
        start: start.point,
        end: end?.point ?? null,
        via: via.map((p) => p.point),
        shape,
        target_m: run.distance_m,
      };
      // Stitched first, so their few fills come out of the budget before the seeds.
      const stitched = await stitch(
        env.orsKey,
        plan,
        history,
        budget,
        progress,
      );
      let tried: RouteCandidate[] = [];
      // After an ORS failure, later runs skip generation; the call-level warning says why.
      if (env.orsKey && budget.failure === null) {
        const before = budget.calls;
        tried = await generate(
          env.orsKey,
          plan,
          want,
          seedBase(run.date, planned.slice(0, index), want),
          budget,
          progress,
        );
        if (budget.failure) {
          if (tried.length === 0)
            runWarnings.push(`No new route was generated: ${budget.failure}.`);
        } else if (before <= 0) {
          runWarnings.push(
            "No new route was generated: this call's routing budget is spent; ask for this run on its own for new routes.",
          );
        } else if (budget.calls <= 0 && index < planned.length - 1) {
          runWarnings.push(
            "This call's routing budget is spent; ask for later runs on their own for new routes.",
          );
        }
      }
      // Stitched and generated routes meet one distance rule.
      let made = [...stitched, ...tried];
      if (shape !== "point-to-point" && made.length > 0) {
        const miss = (c: RouteCandidate) =>
          Math.abs(c.distance_m - run.distance_m);
        const near = made.filter(
          (c) => miss(c) <= run.distance_m * GENERATED_MAX_MISS,
        );
        if (near.length > 0) {
          made = near;
        } else if (via.length > 0) {
          // A via route is what was asked for: the nearest stays, with why it is off. A tie keeps the stitched one, made first.
          const nearest = made.reduce((a, b) => (miss(b) < miss(a) ? b : a));
          made = [nearest];
          const cause =
            nearest.kind === "stitched"
              ? "it follows your past runs between the via points, which cannot be stretched"
              : nearest.distance_m > run.distance_m
                ? "passing the via points alone takes that far from this start"
                : canCall(budget)
                  ? "no detour from it came closer"
                  : "route generation stopped before it could be stretched";
          runWarnings.push(
            `No route through the via points came within ${GENERATED_MAX_MISS * 100}% of ${km(run.distance_m)} km; the nearest, ${km(nearest.distance_m)} km, is offered: ${cause}.`,
          );
        } else {
          made = [];
          runWarnings.push(
            `No new loop close to ${km(run.distance_m)} km was found from this start.`,
          );
        }
      }
      tried = made.filter((c) => c.kind === "generated");
      const kept = made.filter((c) => c.kind === "stitched");

      if (terrain === "hill-repeats") {
        for (const c of made)
          c.hill = bestRepeatHill(c.track.distance, c.track.altitude);
      }
      const all = [...pool, ...made];
      if (all.length > 0 && !crossingsMissing) {
        progress("Counting road crossings", { important: true });
        const nodes = await loadCrossings(all.map((c) => c.track));
        if (nodes === null) crossingsMissing = true;
        else
          for (const c of all)
            c.crossings_per_km = crossingsPerKm(c.track, nodes);
      }

      const ranked = rankPast(pool, run.distance_m, env.today, terrain, bands);
      if (terrain === "hill-repeats")
        ranked.sort((a, b) => Number(!a.hill) - Number(!b.hill));
      const past = ranked.slice(0, MAX_PAST_CANDIDATES);
      // Another recording of a picked loop is the same route, so it is used too.
      for (const c of past) {
        for (const r of cluster?.runs ?? [])
          if (sameRoute(r.track, c.track)) usedPast.add(r.id);
      }
      // The athlete's own lines first, then the most of them, then the distance.
      const ownLines = [...kept].sort(
        (a, b) =>
          (b.history_share ?? 0) - (a.history_share ?? 0) ||
          Math.abs(a.distance_m - run.distance_m) -
            Math.abs(b.distance_m - run.distance_m),
      );
      // Duplicates of a past run go before the cut, so the next route fills the slot.
      candidates = dedupeRoutes([
        ...past,
        ...ownLines,
        ...rankGenerated(tried, terrain, run.distance_m, bands),
      ]).slice(0, past.length + ownLines.length + want);

      if (terrain === "hill-repeats") {
        candidates.sort((a, b) => Number(!a.hill) - Number(!b.hill));
        if (candidates.length > 0 && candidates.every((c) => !c.hill)) {
          runWarnings.push(
            `No candidate has a ${REPEAT_HILL_MIN_M}-${REPEAT_HILL_MAX_M} m stretch at ${REPEAT_HILL_MIN_GRADE_PCT}-${REPEAT_HILL_MAX_GRADE_PCT}% for hill repeats; try terrain hilly, or name a hill with via.`,
          );
        }
      }
    }
    runs.push({
      ...run,
      start: { ...start, history_runs: cluster?.runs.length ?? 0 },
      end,
      via,
      shape,
      terrain,
      candidates,
      warnings: runWarnings,
    });
  }
  if (budget.failure) {
    warnings.push(`Route generation stopped: ${budget.failure}.`);
  }
  if (crossingsMissing) {
    warnings.push(
      "Road crossings could not be counted (OpenStreetMap Overpass did not answer), so new routes were ranked by their share on paths and past runs by recency and distance.",
    );
  }
  return { runs, generation_available: env.orsKey !== null, warnings };
}
